// Write bitplane pointer registers into a copper list.
// BPL1PTH = $DFF0E0, each pointer pair is 4 bytes apart.
static inline USHORT* copSetPlanes(USHORT* cl, const UBYTE** planes, int n) {
    for (int i = 0; i < n; i++) {
        ULONG a = (ULONG)planes[i];
        UWORD reg = 0x00E0 + i * 4;  // BPLxPTH
        *cl++ = reg;
        *cl++ = (UWORD)(a >> 16);
        *cl++ = reg + 2;  // BPLxPTL
        *cl++ = (UWORD)a;
    }
    return cl;
}

// ========================================================================
// Entry point: take system, build copper list, display, wait for click
// ========================================================================
int main() {
    SysBase = *((struct ExecBase**)4UL);
    custom = (struct Custom*)0xdff000;
    GfxBase = (struct GfxBase*)OpenLibrary((CONST_STRPTR)"graphics.library", 0);
    if (!GfxBase) return 0;

    TakeSystem();
    WaitVbl();

    USHORT* copper1 = (USHORT*)AllocMem(30384, MEMF_CHIP);
    USHORT* cl = copper1;

    // Data fetch start/stop — controls which horizontal pixels have bitplane data
    *cl++ = offsetof(struct Custom, ddfstrt); *cl++ = 0x0038;  // lores
    *cl++ = offsetof(struct Custom, ddfstop); *cl++ = 0x00D0;
    // Display window start/stop — visible area on screen
    *cl++ = offsetof(struct Custom, diwstrt); *cl++ = (44<<8)|0x81;  // VSTART=44, HSTART=$81
    *cl++ = offsetof(struct Custom, diwstop); *cl++ = (0x2C<<8)|0xC1;  // VSTOP=300, HSTOP=$C1 (full PAL)
    *cl++ = offsetof(struct Custom, bplcon0); *cl++ = (4<<12)/*BPU*/|(1<<9)/*COLOR*/;  // 0x4200
    *cl++ = offsetof(struct Custom, bplcon1); *cl++ = 0;  // scroll offset = 0
    *cl++ = offsetof(struct Custom, bplcon2); *cl++ = 0x0000;
    *cl++ = 0x0106; *cl++ = 0x0000;  // BPLCON3: bank 0, no LOCT

    *cl++ = offsetof(struct Custom, bpl1mod); *cl++ = 120;
    *cl++ = offsetof(struct Custom, bpl2mod); *cl++ = 120;

    const UBYTE* planes[4];
    for (int i = 0; i < 4; i++)
        planes[i] = (const UBYTE*)fantasy_planes + 40 * i;
    cl = copSetPlanes(cl, planes, 4);

    // Bank-swap CAP: initialize bank 0 (line 0) and bank 1 (line 1)
    *cl++ = 0x0106; *cl++ = 0x0000;  // BPLCON3: bank 0, LOCT=0
    for (int i = 0; i < 16; i++) {
        *cl++ = offsetof(struct Custom, color) + i * 2;
        *cl++ = fantasy_bs_bank0_hi[i];
    }
    *cl++ = 0x0106; *cl++ = 0x0200;  // LOCT=1
    for (int i = 0; i < 16; i++) {
        *cl++ = offsetof(struct Custom, color) + i * 2;
        *cl++ = fantasy_bs_bank0_lo[i];
    }
    *cl++ = 0x0106; *cl++ = 0x2000;  // bank 1, LOCT=0
    for (int i = 0; i < 16; i++) {
        *cl++ = offsetof(struct Custom, color) + i * 2;
        *cl++ = fantasy_bs_bank1_hi[i];
    }
    *cl++ = 0x0106; *cl++ = 0x2200;  // bank 1, LOCT=1
    for (int i = 0; i < 16; i++) {
        *cl++ = offsetof(struct Custom, color) + i * 2;
        *cl++ = fantasy_bs_bank1_lo[i];
    }
    *cl++ = 0x0106; *cl++ = 0x0000;  // bank 0, LOCT=0

    const struct CopperEntry* p_hi = fantasy_bs_hi;
    const struct CopperEntry* p_lo = fantasy_bs_lo;

    for (int y = 0; y < 213; y++) {
        USHORT line = y + 44 - 1;
        if (line == 256) {
            *cl++ = 0xFFDF; *cl++ = 0xFFFE;
        }
        *cl++ = ((line & 0xFF) << 8) | 0xDD;
        *cl++ = 0xfffe;
        int wb = (y + 1) & 1;  // write bank = next display bank
        *cl++ = 0x0106;
        *cl++ = (UWORD)(wb << 13);  // LOCT=0 (hi nibbles)
        int n = fantasy_bs_n[y];
        for (int s = 0; s < n; s++) {
            *cl++ = offsetof(struct Custom, color) + p_hi->reg * 2;
            *cl++ = p_hi->color;
            p_hi++;
        }
        if (n > 0) {
            *cl++ = 0x0106;
            *cl++ = (UWORD)((wb << 13) | 0x0200);
            for (int s = 0; s < n; s++) {
                *cl++ = offsetof(struct Custom, color) + p_lo->reg * 2;
                *cl++ = p_lo->color;
                p_lo++;
            }
        }
    }

    *cl++ = (1<<8)|1; *cl++ = 0xfffe;  // WAIT line 257
    *cl++ = offsetof(struct Custom, bplcon0); *cl++ = (1<<9)/*COLOR*/;  // 0 planes, blank below image
    *cl++ = 0xffff; *cl++ = 0xfffe;

    // Turn off floppy motor (select DF0, motor off, deselect)
    *(volatile UBYTE*)0xbfd100 &= ~(1<<3);  // select DF0
    *(volatile UBYTE*)0xbfd100 |=  (1<<7);   // motor off
    *(volatile UBYTE*)0xbfd100 |=  (1<<3);   // deselect DF0

    custom->cop1lc = (ULONG)copper1;
    custom->dmacon = DMAF_BLITTER;
    custom->copjmp1 = 0x7fff;
    custom->dmacon = DMAF_SETCLR | DMAF_MASTER | DMAF_RASTER | DMAF_COPPER;

    while (!MouseLeft()) { WaitVbl(); }

    FreeSystem();
    FreeMem(copper1, 30384);
    CloseLibrary((struct Library*)GfxBase);

    // Exit message
    { struct Library* DOSBase = OpenLibrary((CONST_STRPTR)"dos.library", 0);
      if (DOSBase) {
        static const char msg[] = "\n\033[1;33m                 ___            _\n  _ __ _ _  __ _|_  )__ _ _ __ (_)__ _ __ _\n | '_ \\ ' \\/ _` |/ // _` | '  \\| / _` / _` |\n | .__/_||_\\__, /___\\__,_|_|_|_|_\\__, \\__,_|\n |_|       |___/                 |___/\n\033[0m\n  fantasy\n  320x213, 4bpl, 16 colors, AGA 24-bit\n  34080 bytes bitplane data\n  Copper: 15 changes/line\n\n  \033[36mhttps://www.png2amiga.app\033[0m\n\n";
        BPTR fh = Output();
        if (fh) Write(fh, (APTR)msg, 362);
        CloseLibrary(DOSBase);
    } }

    return 0;
}
